			this.renderThickUpperWire(pose, vc, light, overlay, te, 0.5);
			this.renderThickLowerWire(pose, vc, light, overlay, te, -0.5);

			this.renderThinWire(pose, vc, light, overlay, te, 0);
			this.renderThinWire(pose, vc, light, overlay, te, 0.2);
			this.renderThinWire(pose, vc, light, overlay, te, -0.2);
