		Shape2n.render(pose, vc, light, overlay);
		Shape2o.render(pose, vc, light, overlay);
		Shape2p.render(pose, vc, light, overlay);
		Shape2q.render(pose, vc, light, overlay);
		Shape2r.render(pose, vc, light, overlay);
